APPROVED_SELF_AST = 'e607da846f681d3f565fe5e695784997229cb9135e34ac69925852a92ec22f6d'

def _digest(source):
    return sha256(ast.unparse(ast.parse(source)).encode()).hexdigest()

def _read(root, relative):
    if type(relative) is not str or not relative.endswith('.py') or (not relative.startswith(('src/', 'scripts/', 'pipelines/', 'research/'))) or ('..' in relative.split('/')) or ('\\' in relative):
        raise ValueError('Native reader successor source path is malformed')
    path = root / relative
    if not path.is_file() or path.is_symlink() or root not in path.resolve().parents:
        raise ValueError('Native reader successor source is missing or foreign: ' + relative)
    return path.read_text(encoding='utf-8')

def certify_native_channel_keeper_successor_source():
    root = Path(__file__).resolve().parents[2]
    own = 'src/backend/backtest_native_channel_keeper_successor_certification.py'
    text = _read(root, own)
    tree = ast.parse(text)
    declarations = {'PARENT_SOURCE_AST': PARENT_SOURCE_AST, 'REQUIRED_SOURCE_AST': REQUIRED_SOURCE_AST, 'APPROVED_SELF_AST': APPROVED_SELF_AST}
    fresh = {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            name = node.targets[0].id
            if name in declarations:
                if name in fresh:
                    raise ValueError('Native source declaration repeats')
                fresh[name] = ast.literal_eval(node.value)
                node.value = ast.Constant(None)
    if fresh != declarations or _digest(ast.unparse(tree)) != APPROVED_SELF_AST:
        raise ValueError('Native reader successor certifier envelope differs')
    if not PARENT_SOURCE_AST or not REQUIRED_SOURCE_AST or (not set(PARENT_SOURCE_AST) <= set(REQUIRED_SOURCE_AST)) or (own in REQUIRED_SOURCE_AST) or any((type(pin) is not str or len(pin) != 64 or any((c not in '0123456789abcdef' for c in pin)) for pin in (*PARENT_SOURCE_AST.values(), *REQUIRED_SOURCE_AST.values()))):
        raise ValueError('Native reader successor source inventory is incomplete or malformed')
    from .backtest_native_channel_keeper_successor_compatibility import restore_native_channel_keeper_successor_parent_source
    sealed = [(own, text)]
    observed = [(own, sha256(text.encode()).hexdigest())]
    for relative, expected in REQUIRED_SOURCE_AST.items():
        current = _read(root, relative)
        if _digest(current) != expected:
            raise ValueError('Native reader successor executing source differs: ' + relative)
        if relative in PARENT_SOURCE_AST:
            retained = restore_native_channel_keeper_successor_parent_source(current, relative)
            if _digest(retained) != PARENT_SOURCE_AST[relative]:
                raise ValueError('Native reader successor complete inherited source differs: ' + relative)
        sealed.append((relative, current))
        observed.append((relative, sha256(current.encode()).hexdigest()))
    for relative, current in sealed:
        if _read(root, relative) != current:
            raise ValueError('Native reader successor source changed during certification: ' + relative)
    return sha256(json.dumps(observed, separators=(',', ':')).encode()).hexdigest()
